-- ============================================================================
-- ReviewRadar — ONE FILE: reviews table + demo account data (The Coffee Concept)
-- Run once in Supabase → SQL Editor → New query → paste ALL → Run. Safe to re-run.
-- No email needed. Requires supabase_setup.sql to have been run before (businesses table).
-- ============================================================================

-- 1. businesses: extra columns + allow a public DEMO business with no owner ---
alter table businesses add column if not exists maps_url        text;
alter table businesses add column if not exists google_place_id text;
alter table businesses add column if not exists is_demo         boolean not null default false;
alter table businesses alter column user_id drop not null;
alter table businesses drop constraint if exists businesses_owner_or_demo;
alter table businesses add constraint businesses_owner_or_demo check (user_id is not null or is_demo);

-- Customers must never be able to mark their own business as public demo data.
create or replace function rr_lock_is_demo() returns trigger language plpgsql as $$
begin
  if coalesce(auth.role(), 'service_role') = 'authenticated' then
    if tg_op = 'INSERT' then new.is_demo := false; else new.is_demo := old.is_demo; end if;
  end if;
  return new;
end $$;
drop trigger if exists rr_lock_is_demo on businesses;
create trigger rr_lock_is_demo before insert or update on businesses
  for each row execute function rr_lock_is_demo();

drop policy if exists "Anyone can view demo businesses" on businesses;
create policy "Anyone can view demo businesses" on businesses for select using (is_demo = true);

-- 2. reviews table ------------------------------------------------------------
create table if not exists reviews (
  id              uuid primary key default gen_random_uuid(),
  business_id     uuid not null references businesses(id) on delete cascade,
  platform        text not null default 'google',
  external_id     text not null,            -- Google's own review ID (no duplicates on re-scrape)
  author          text not null default 'Anonymous',
  rating          smallint check (rating between 1 and 5),
  text            text not null default '',
  published_at    timestamptz,              -- ORIGINAL review date (drives the weekly chart)
  sentiment       text check (sentiment in ('positive','neutral','negative')),
  sentiment_score numeric(4,3),
  is_demo         boolean not null default false,
  created_at      timestamptz not null default now(),
  unique (business_id, external_id)
);
create index if not exists reviews_business_date_idx on reviews (business_id, published_at desc);
alter table reviews enable row level security;

drop policy if exists "Users can view own reviews" on reviews;
create policy "Users can view own reviews" on reviews for select
  using (exists (select 1 from businesses b where b.id = reviews.business_id and b.user_id = auth.uid()));

drop policy if exists "Anyone can view demo reviews" on reviews;
create policy "Anyone can view demo reviews" on reviews for select
  using (exists (select 1 from businesses b where b.id = reviews.business_id and b.is_demo));
-- No insert/update/delete policy on purpose: only the Edge Function (service role)
-- and this SQL editor can write reviews. Browsers cannot.

-- 3. Demo business + 249 real reviews ------------------------------------------
do $body$
declare v_biz uuid;
begin
  select id into v_biz from businesses where is_demo and place_id = 'ChIJWXVE9FqvgTkRz2FJHcAe2y0' limit 1;
  if v_biz is null then
    insert into businesses (user_id, place_id, google_place_id, name, address, rating, platforms, is_demo)
    values (null, 'ChIJWXVE9FqvgTkRz2FJHcAe2y0', 'ChIJWXVE9FqvgTkRz2FJHcAe2y0',
            'The Coffee Concept Jabalpur', 'Wright Town, Jabalpur, Madhya Pradesh 482002', 4.5, '{google}', true)
    returning id into v_biz;
  end if;

  insert into reviews (business_id, platform, external_id, author, rating, text, published_at, is_demo)
  select v_biz, 'google', x.external_id, x.author, x.rating, x.text, x.published_at, true
  from jsonb_to_recordset($rr$[{"external_id": "Ci9DQUlRQUNvZENodHljRjlvT21GTVNtOUNORVI0YVdnMlVXMUZZUzFOYjBkR01FRRAB", "author": "HARSH GAMERZ", "rating": 5, "text": "", "published_at": "2026-10-02T11:12:31.089Z"}, {"external_id": "Ci9DQUlRQUNvZENodHljRjlvT25WcVVrRjJNR1J3VVdJNGFUbFJVbUpSVEhKNVdFRRAB", "author": "Antara Jain", "rating": 3, "text": "", "published_at": "2026-10-02T07:41:43.134Z"}, {"external_id": "Ci9DQUlRQUNvZENodHljRjlvT2xsVVptVnNaVEkwWVZCSVIzUnNTRkJaVjE4NVIwRRAB", "author": "Eklavya Gupta", "rating": 5, "text": "", "published_at": "2026-09-30T13:53:50.974Z"}, {"external_id": "Ci9DQUlRQUNvZENodHljRjlvT21wZmJtOWxOV1ZZV1ZWd1VWcFdiVVJRVTJocVoxRRAB", "author": "Neeraj Nagaich", "rating": 5, "text": "Great coffee with good vibes.. cold coffee frappe & cappuccino excellent aromatic  ...service was authentic by Rohit rathoure. Keep it up", "published_at": "2026-09-30T06:18:15.005Z"}, {"external_id": "Ci9DQUlRQUNvZENodHljRjlvT25sS1ZrZDZYM0JIWXpWb09GUjJUSFJETlZkbWNFRRAB", "author": "Palash Backup", "rating": 5, "text": "", "published_at": "2026-09-27T10:20:58.836Z"}, {"external_id": "Ci9DQUlRQUNvZENodHljRjlvT210d1VHZDJZbVF4ZFU1VlNXWnhVVE56UlVwdlJtYxAB", "author": "Pooja Patel", "rating": 1, "text": "As everything was perfect ....... It felt like so cozy and comfort zoneee..❤️", "published_at": "2026-09-26T17:41:43.411Z"}, {"external_id": "Ci9DQUlRQUNvZENodHljRjlvT2t0SFVXeHNlRGRmWmxoMlVsRjZWUzAzVlVadk0yYxAB", "author": "Mona Jindwani", "rating": 3, "text": "My experience of this place was average; it was suitable for a one-time visit. The food was good; I ordered burnt garlic noodles and mixed sauce pasta. The coffee did not make the cut; it was too sugary. The food was served on thermocol plates. The service was slow. The portion size was smaller than the price we paid. The ambience was nice for hanging out. The place has good potential. I would suggest the owner improve the service, the coffee, and the portion size.", "published_at": "2026-09-25T12:18:39.765Z"}, {"external_id": "Ci9DQUlRQUNvZENodHljRjlvT2tkQ2JXSkplR0Z1VWs5eFJ5MTVVRVJWVjA1QlpGRRAB", "author": "Simran Sharma", "rating": 5, "text": "Taste was amazing and brilliant services provided by Rohit Rathore must visit 😋😍", "published_at": "2026-09-25T07:42:42.499Z"}, {"external_id": "Ci9DQUlRQUNvZENodHljRjlvT25ONVRVbDJNV0phVTJGMGVXOU5Semd0UVc5WVMyYxAB", "author": "Meghna Mukhopadhyay", "rating": 1, "text": "", "published_at": "2026-09-20T12:09:42.948Z"}, {"external_id": "Ci9DQUlRQUNvZENodHljRjlvT2xCVWVFc3hPRFJFWVd0aFdtcG1VV3RVTm1kaGJWRRAB", "author": "Aafreen Zabi", "rating": 5, "text": "", "published_at": "2026-09-20T10:22:21.172Z"}, {"external_id": "Ci9DQUlRQUNvZENodHljRjlvT2s5clduSlNhbWd4Vmt4NVRVcGZiMmt5YkZOZlNVRRAB", "author": "Moira Agrawal", "rating": 1, "text": "Cutlery not available also quality and quantity of food was also very poor … would never recommend someone", "published_at": "2026-09-16T09:27:13.069Z"}, {"external_id": "Ci9DQUlRQUNvZENodHljRjlvT2xsSVUyMXpiR2hFWDJsQmVIbE5XbEYwY3pjMlRsRRAB", "author": "Ashutosh Goswami", "rating": 5, "text": "", "published_at": "2026-09-15T13:31:17.444Z"}, {"external_id": "Ci9DQUlRQUNvZENodHljRjlvT2pSaldHSkZjMGwwWTBwemNrTkdWSGh1T1UxTExYYxAB", "author": "Ravidas Ahirwar", "rating": 5, "text": "Food is very delicious 😋 nd cold coffee brownie 🤤", "published_at": "2026-09-07T15:12:04.161Z"}, {"external_id": "Ci9DQUlRQUNvZENodHljRjlvT2toNGVWZzRUVzkwYnpSWFFta3hlRlpPY2pNMU9HYxAB", "author": "yatnesh kumar pusham", "rating": 5, "text": "Hot chocolate is amazing ✨", "published_at": "2026-09-07T05:24:40.312Z"}, {"external_id": "Ci9DQUlRQUNvZENodHljRjlvT210eVh5MUxhVkpYYTJSUVgxWm9iWGhyWVROb1RuYxAB", "author": "Aman Rai", "rating": 2, "text": "", "published_at": "2026-09-02T10:04:44.619Z"}, {"external_id": "Ci9DQUlRQUNvZENodHljRjlvT2xWa2N6RnJNWE5GZFRka1lqQlhjMXBxVTBoZmEwRRAB", "author": "Suman Sharma", "rating": 5, "text": "", "published_at": "2026-08-30T11:06:42.330Z"}, {"external_id": "Ci9DQUlRQUNvZENodHljRjlvT2tOTmNqa3RaemxtT